        heading: 'マス目の基本ルール',
        body: `■ 一マス一字が原則
ひらがな・カタカナ・漢字・句読点・かぎかっこ・中点（・）は、すべて一マス一字として数える。「四十字以内」なら、句読点も含めて四十マス以内に収める。

■ 書き出し
作文では段落の初めを一字下げるが、記述解答は一字下げをしない。一マス目から書き始める。下げると一字損をする。

■ 行末の句読点
縦書きのマス目で、行の最後のマスに「。」が来ることがある。作文では最後のマスに文字と句点を一緒に入れる（ぶら下げる）が、記述解答では厳密に問われないことが多い。安全なのは、句点を次の行の一マス目に書く方法。どちらでも減点しない学校が大半である。

■ 数字
・縦書き → 漢数字（「三十年」＝三マス）
・横書き → 算用数字。一マスに二桁まで入れる（「30年」＝「30」で一マス＋「年」で一マス）
迷ったら漢数字で書くと、どちらの向きでも通用する。

■ かぎかっこ
「　」は開き・閉じでそれぞれ一マス。本文から語句を引用するとき、かぎかっこを付けるかどうかは自由だが、付けると二字ぶん字数を使う。字数が厳しいときは付けなくてよい。

■ 記号
！や？は記述解答ではふつう使わない。読点は「、」を使い、コンマ（,）は使わない。

★ ポイント：形式は覚えれば必ず守れる。内容と違って、努力が確実に一点になる領域である。`,
