        body: `■ ステップ1：模範解答を要素に切る
模範解答に「／」を入れ、番号を振る。
例）「検索は求めた情報だけを返すため、／辞書のように偶然目に入った語から／関心が広がる機会が失われる／点。」
　→ ①②③＋語尾の四項目。

■ ステップ2：配点を推定する
満点が8点なら、①2点／②3点／③2点／語尾1点、というように割り振る。抽象度の高い項目に多く配る。

■ ステップ3：自分の答案に番号を書きこむ
自分の答案の該当箇所に①②③と書く。書けない番号が「抜けた要素」である。

■ ステップ4：抜けた理由を分類する
（あ）本文のその箇所を読んでいなかった → 読解の問題
（い）読んだが要素だと気づかなかった → 取り出し口の問題
（う）気づいたが字数の都合で切った → 優先順位の問題
（え）書いたが表現が不十分で伝わらない → 表現の問題

■ ステップ5：一つだけ対策を決める
「次は『つまり』の後を必ず見る」など、行動を一つに絞る。三つ決めると実行されない。

★ ポイント：（あ）〜（え）のどれが多いかで、やるべき練習が変わる。（あ）が多ければ読解演習、（う）が多ければ字数設計、（え）が多ければ言いかえの練習。

⚠ 注意：模範解答と一字一句同じである必要はない。「同じ内容が書かれているか」で判定する。厳しすぎる自己採点は、かえって改善点を見えなくする。`,
