【設問】傍線部「その日から、私は弁当を残さなくなった」とあるが、それはなぜか。六十字以内で説明しなさい。（8点）

【原因の候補】
　（ア）母が野菜の値段表を見ていた
　（イ）ピーマンだけが赤字で丸をしてあった＝安いものを選んで工夫していた
　（ウ）母の行為が嫌がらせではなく、やりくりの中の心づかいだと分かった
　（エ）それまで反抗して残していた（対比）

