        body: `■ 型
　［部品Aの言いかえ］＋［部品Bの言いかえ］＋ということ。

■ 言いかえるべき四つ
①比喩：「心の窓が開いた」「氷のような視線」「時間に追われる」
②抽象語：「本質」「関係性」「主体性」「価値」「構造」
③指示語：「それ」「そのこと」「こうした状況」
④独特な言い回し：筆者が造った言葉、かぎかっこ付きの語

■ 言いかえなくてよいもの
だれが読んでも同じ像を結ぶ具体語（雨・机・母・学校）。これらは言いかえるとかえって遠回りになる。

■ 検算法（入れかえて読む）
自分の答案から「ということ。」を外し、本文の傍線部の位置に入れて読む。前後とつながって意味が通れば正しい。
例）傍線部「時間に追われている」
　答案「自分で決めたはずの予定に、かえって自分が縛られている」
　入れかえ「私たちはいつのまにか、自分で決めたはずの予定に、かえって自分が縛られている。」→ 通る。○

■ 通らない例
　答案「とても忙しい」
　入れかえ「私たちはいつのまにか、とても忙しい。」→ 文としては通るが、本文の論（効率を求めた結果という文脈）が消えている。△
言いかえが浅いと、文としては通っても要素点が付かない。

★ ポイント：言いかえの深さは「本文の他の部分の言葉を使えているか」で測れる。傍線部の周辺の語を使って言いかえられていれば、たいてい要素点が付く。`,
