        heading: '部品分けの手順',
        body: `■ どこで切るか
・読点（、）の位置
・「〜が」「〜のに」「〜ながら」などの接続の助詞
・「AではなくB」の「ではなく」
・「AでありB」の「であり」

例）傍線部「便利さは、人を自由にすると同時に、人から選ぶ力を奪う」
　→ ①便利さは人を自由にする ／ ②同時に ／ ③人から選ぶ力を奪う
　部品は三つ。②の「同時に」は「一方で」という対比の目印なので、答案では「〜と同時に」「〜一方で」の形で残す。

■ 部品ごとの判定
①「人を自由にする」→ 何がどう自由になるのか、本文で確認（選択肢が増える／制約が減る）
②「同時に」→ 対比の接続。言いかえ不要だが、答案から落とすと構造が崩れる
③「選ぶ力を奪う」→ 抽象。本文で確認（比較に疲れて選択をやめる）

■ 組み立て
　［①の言いかえ］が、同時に［③の言いかえ］ということ。
　例）「選べるものが増えて制約から解放される一方で、比較に疲れて自分で選ぶことをやめてしまうということ。」

■ 部品の数と字数
・部品2つ　→ 四十〜五十字
・部品3つ　→ 六十〜七十字
・部品4つ　→ 八十字以上
指定字数と部品数が合わないときは、部品分けが細かすぎるか粗すぎる。

★ ポイント：部品分けをすると、字数配分も同時に決まる。六十字で部品三つなら、一部品あたり十八字前後である。`,
