        body: `■ 型
　［前の心情］だったが、［きっかけ］によって、［後の心情］に変わった。

■ 三要素の探し方
・前の心情 → 傍線部よりずっと前。場面の初め、または人物が最初に登場する場面。
・きっかけ → 前の心情と傍線部のあいだにある出来事。一つに絞る。
・後の心情 → 傍線部の周辺。行動・表情・情景から読み取る。

■ 字数配分（六十字の場合）
・前の心情　　15字
・きっかけ　　18字
・後の心情　　22字
・語尾　　　　 5字
後の心情を厚くするのは、設問が最終的に問うているのがそこだからである。

■ よくある失敗
①後の心情しか書かない → 変化になっていない。半分以下。
②きっかけを二つ以上書く → 字数が足りなくなり、心情が薄くなる。
③前の心情を傍線部の直前から取る → 直前は変化の途中であることが多い。もっと前を探す。

■ 変化のパターン
・反発 → 理解（相手の事情を知る）
・不安 → 安堵（結果が分かる）
・自信 → 挫折（失敗する）
・無関心 → 当事者意識（自分に関わることだと気づく）
・拒絶 → 受容（時間が経つ、第三者の言葉）

★ ポイント：物語文の心情変化は、たいてい「他者の言動」か「物の発見」がきっかけになる。この二つを探せば、きっかけは高い確率で見つかる。`,
