　後：見えない努力や事情があると知り、人を来た回数で判断しなくなった

【模範解答（70字）】
　練習に来ない先輩をやる気がないと決めつけて怒っていたが、人目を避けて練習する姿を見て、見えない事情があると気づく気持ちに変わった。

