        heading: '実際の設問で確かめる（三候補から一つを選ぶ）',
        body: `【本文（要約・行番号つき）】
　（1）読書は知識を増やすためのものだと言われる。（2）確かに本には情報が詰まっている。（3）だが情報を得るだけなら、要約を読めば足りる。（4）本を最後まで読む意味は、著者が考えを組み立てていく順序を、自分の頭でたどり直すところにある。（5）読書とは、答えを受け取ることではなく、考える手つきを借りることなのだ。

【設問】傍線部（5）「考える手つきを借りる」とはどういうことか。それを具体的に説明した部分を、本文中から二十五字以内で抜き出しなさい。（4点）

【候補の洗い出し】
　候補ア（1行目）：「知識を増やすためのもの」（12字）
　候補イ（2行目）：「本には情報が詰まっている」（13字）
　候補ウ（4行目）：「著者が考えを組み立てていく順序を、自分の頭でたどり直す」（27字）

【絞りこみ】
　・候補ア → 一般論（「〜と言われる」）。筆者の主張ではない。外す。
　・候補イ → 情報の話。「考える手つき」の説明になっていない。外す。
　・候補ウ → 内容は完全に合致。ただし27字で字数超過。

【字数の調整】
　「考えを組み立てていく順序を自分の頭でたどり直す」（24字）
　→ 「著者が」を外し、読点も外した区間なら24字で条件を満たす。本文にこの連続した区間が存在するかを確認する。

【解答】考えを組み立てていく順序を自分の頭でたどり直す（24字）
　※本文が「著者が考えを組み立てていく順序を、自分の頭でたどり直す」なら、読点を含むため区間の取り方に注意する。読点を含めて25字以内に収まる形で切る。

【部分点の内訳（4点）】
・正しい箇所（4行目）を選んでいる…………… 2点
・字数条件（25字以内）を満たしている……… 1点
・区切りが文法的に自然な位置である………… 1点

■ 候補アを選んだ場合（0点）
「知識を増やすためのもの」は、（3）で「情報を得るだけなら要約で足りる」と否定されている。一般論であり、筆者の主張ではない。

■ 語の一致に引っかかる例
傍線部に「考える」があるので、本文中の「考え」を含む箇所を反射的に選びたくなる。（1）（4）（5）すべてに「考え」に近い語があるが、答えは内容で決まる。

★ ポイント：抜き出しの誤答の大半は「一般論を選んだ」「否定された内容を選んだ」のどちらかである。この二つを外すだけで、正答率は大きく上がる。`,
