        body: `■ 重複表現（意味が重なっている）
・まず最初に　→「まず」または「最初に」
・約十分ほど　→「約十分」または「十分ほど」
・後で後悔する　→「後悔する」
・必ず〜する必要がある　→「〜する必要がある」
・一番最後　→「最後」
・違和感を感じる　→「違和感を覚える」
・頭痛が痛い　→「頭が痛い」

■ 冗長表現（削っても意味が変わらない）
・〜ということができる（10字）　→ 削る
・〜のである（4字）　→ 削る
・〜という点において（7字）　→「〜で」
・〜することによって（8字）　→「〜して」
・〜においては（5字）　→「〜では」
・〜であると考えられる（9字）　→「〜である」

■ 内容の重複
同じ要素を別の言葉で二度書くこと。
例）「情報が増えて選択肢が多くなり、選ぶものがたくさんあるので迷う」
　→ 「情報が増える」「選択肢が多くなる」「選ぶものがたくさんある」は同じ内容。一つに統合する。
　→ 「選択肢が増えて迷う」（10字）

■ 同語反復
一つの答案で同じ語を三回以上使うと、くどい印象になる。
例）「〜が変わることで、〜も変わり、その結果〜が変わる」
　→ 「移る」「入れかわる」など、別の語を混ぜる。

■ 削った字数の使い道
冗長表現を削ると、六十字の答案なら十〜十五字が生まれる。これは要素一つ分である。削って短くするのではなく、削って要素を足すのが正しい使い方。

★ ポイント：答案を書いたら「削れる字数」を数える。十字以上あれば、その分だけ要素が入れられたということ。`,
